        case 615: // In <BLOCKCOMMENT> Recognized '"*"',	Shortest string "*"
/* lone star, not followed by slash */
            break;
        case 616: // In <BLOCKCOMMENT> Recognized '"*/"',	Shortest string "*/"
yy_pop_state();
            break;
        case 617: // In <DOLLARQUOTE> Recognized '[^$]+',	Shortest string "-"
AppendDollarQuote(yytext);
            break;
        case 618: // In <DOLLARQUOTE> Recognized '"$"',	Shortest string "$"
AppendDollarQuote(yytext);
            break;
        case 619: // In <DOLLARQUOTE> Recognized '{DollarQuote}',	Shortest string "$$"
if (EndsDollarQuote(yytext)) { yy_pop_state(); yylval.s = TakeDollarQuote(); return (int)Token.TDOLLARQUOTED; } AppendDollarQuote(yytext.Substring(0, yyleng - 1)); yyless(yyleng - 1);
            break;
        default:
            break;
    }
#pragma warning restore 162, 1522
#endregion
                    }
                }
        }

#if BACKUP
        void SaveStateAndPos(ref Context ctx) {
            ctx.bPos  = buffer.Pos;
            ctx.rPos  = readPos;
            ctx.cCol  = cCol;
            ctx.lNum  = lNum;
            ctx.state = state;
            ctx.cChr  = code;
        }

        void RestoreStateAndPos(ref Context ctx) {
            buffer.Pos = ctx.bPos;
            readPos = ctx.rPos;
            cCol  = ctx.cCol;
            lNum  = ctx.lNum;
            state = ctx.state;
            code  = ctx.cChr;
        }
#endif  // BACKUP

        // ============= End of the tokenizer code ================

#if STACK        
        [SuppressMessage("Microsoft.Performance", "CA1811:AvoidUncalledPrivateCode")]
        internal void yy_clear_stack() { scStack.Clear(); }
        
        [SuppressMessage("Microsoft.Performance", "CA1811:AvoidUncalledPrivateCode")]
        internal int yy_top_state() { return scStack.Peek(); }
        
        internal void yy_push_state(int state)
        {
            scStack.Push(currentScOrd);
            BEGIN(state);
        }
        
        internal void yy_pop_state()
        {
            // Protect against input errors that pop too far ...
            if (scStack.Count > 0) {
				int newSc = scStack.Pop();
				BEGIN(newSc);
            } // Otherwise leave stack unchanged.
        }
 #endif // STACK

        [SuppressMessage("Microsoft.Performance", "CA1811:AvoidUncalledPrivateCode")]
        internal void ECHO() { Console.Out.Write(yytext); }
        
    } // end class $Scanner


} // end namespace
